syntax = "proto3";

package energy.v1;

// The site-readings service. Field numbers in this file are part of the wire
// contract: once committed, they must not be reused or renumbered.
service EnergyService {
  // Returns the current (first) reading for one site.
  rpc GetReading(GetReadingRequest) returns (Reading);

  // Returns readings for one site in source order. The limit is optional;
  // when it is absent every reading is returned, and when it is present but
  // zero an empty stream is returned.
  rpc StreamReadings(StreamReadingsRequest) returns (stream Reading);
}

message GetReadingRequest {
  string site_id = 1;
}

message StreamReadingsRequest {
  string site_id = 1;

  // `optional` preserves field presence so "no limit" is distinguishable from
  // an explicit limit of zero. A negative value is rejected as invalid_limit.
  optional int32 limit = 2;
}

message Reading {
  string site_id = 1;
  int64 watts = 2;
  int64 at_ms = 3;
}

"use strict";

/**
 * Hand-written gRPC framing and protobuf codec.
 *
 * The deployment has no third-party packages, so this module implements only
 * the protobuf features used by proto/energy.proto:
 *
 *   - gRPC message framing: 1 compressed-flag byte + 4-byte big-endian length,
 *     followed by the protobuf message bytes;
 *   - protobuf varints, length-delimited strings, int32 and int64 fields;
 *   - tolerant decoding of unknown fields (they are skipped, as proto3
 *     requires).
 *
 * Message field numbers match proto/energy.proto and must stay in sync with it.
 */

const FRAME_HEADER_BYTES = 5;
const DEFAULT_MAX_MESSAGE_BYTES = 4 * 1024 * 1024;

class WireError extends Error {
  constructor(message) {
    super(message);
    this.name = "WireError";
    this.code = "wire";
  }
}

function assertSafeInteger(value, what) {
  if (typeof value !== "number" || !Number.isSafeInteger(value)) {
    throw new WireError(`${what}_must_be_a_safe_integer`);
  }
  return BigInt(value);
}

/** Encode an unsigned 64-bit varint (negative values use two's complement). */
function encodeVarint(value) {
  let remaining;
  if (typeof value === "bigint") {
    remaining = BigInt.asUintN(64, value);
  } else {
    remaining = BigInt.asUintN(64, assertSafeInteger(value, "varint"));
  }
  const bytes = [];
  do {
    let byte = Number(remaining & 0x7fn);
    remaining >>= 7n;
    if (remaining !== 0n) byte |= 0x80;
    bytes.push(byte);
  } while (remaining !== 0n);
  return Buffer.from(bytes);
}

/** Decode one unsigned 64-bit varint, returning its raw BigInt value. */
function decodeVarint(buffer, offset = 0) {
  let value = 0n;
  let shift = 0n;
  let index = offset;
  for (let count = 0; count < 10; count += 1) {
    if (index >= buffer.length) throw new WireError("truncated_varint");
    const byte = buffer[index];
    index += 1;
    value |= BigInt(byte & 0x7f) << shift;
    if ((byte & 0x80) === 0) return { value, offset: index };
    shift += 7n;
  }
  throw new WireError("varint_too_long");
}

function encodeTag(fieldNumber, wireType) {
  if (!Number.isInteger(fieldNumber) || fieldNumber < 1) {
    throw new WireError("invalid_field_number");
  }
  return encodeVarint((BigInt(fieldNumber) << 3n) | BigInt(wireType));
}

function encodeStringField(fieldNumber, value) {
  if (typeof value !== "string") throw new WireError("string_field_requires_a_string");
  const bytes = Buffer.from(value, "utf8");
  return Buffer.concat([encodeTag(fieldNumber, 2), encodeVarint(bytes.length), bytes]);
}

function encodeInt32Field(fieldNumber, value) {
  if (!Number.isInteger(value) || value < -2147483648 || value > 2147483647) {
    throw new WireError("int32_out_of_range");
  }
  // int32 values are sign-extended to a 64-bit varint on the wire.
  return Buffer.concat([encodeTag(fieldNumber, 0), encodeVarint(BigInt(value))]);
}

function encodeInt64Field(fieldNumber, value) {
  if (typeof value === "number") {
    if (!Number.isSafeInteger(value)) throw new WireError("int64_out_of_range");
  } else if (typeof value === "bigint") {
    if (value < -(1n << 63n) || value > (1n << 63n) - 1n) {
      throw new WireError("int64_out_of_range");
    }
  } else {
    throw new WireError("int64_out_of_range");
  }
  return Buffer.concat([encodeTag(fieldNumber, 0), encodeVarint(value)]);
}

function wireTypeFor(kind) {
  return kind === "string" ? 2 : 0;
}

function defaultFor(kind) {
  return kind === "string" ? "" : 0;
}

function convertVarint(kind, raw) {
  switch (kind) {
    case "int32":
      return Number(BigInt.asIntN(32, raw));
    case "int64":
      return Number(BigInt.asIntN(64, raw));
    default:
      throw new WireError("unsupported_varint_kind");
  }
}

/**
 * Field descriptors. These are the single source of truth for both enum and
 * decode; proto/energy.proto is the human-facing declaration of the same
 * contract.
 */
const MESSAGE_DEFINITIONS = Object.freeze({
  GetReadingRequest: Object.freeze([
    Object.freeze({ number: 1, name: "siteId", kind: "string" }),
  ]),
  StreamReadingsRequest: Object.freeze([
    Object.freeze({ number: 1, name: "siteId", kind: "string" }),
    Object.freeze({ number: 2, name: "limit", kind: "int32", optional: true }),
  ]),
  Reading: Object.freeze([
    Object.freeze({ number: 1, name: "siteId", kind: "string" }),
    Object.freeze({ number: 2, name: "watts", kind: "int64" }),
    Object.freeze({ number: 3, name: "atMs", kind: "int64" }),
  ]),
});

function definitionFor(type) {
  const definition = MESSAGE_DEFINITIONS[type];
  if (definition === undefined) throw new WireError(`unknown_message_type:${type}`);
  return definition;
}

function encodeMessage(type, value) {
  if (value === null || typeof value !== "object") {
    throw new WireError(`${type}_must_be_an_object`);
  }
  const chunks = [];
  for (const field of definitionFor(type)) {
    const provided = Object.prototype.hasOwnProperty.call(value, field.name) && value[field.name] !== undefined;
    if (field.optional === true) {
      // Presence matters for optional fields: an explicit zero must be encoded.
      if (!provided) continue;
    } else {
      const defaultValue = defaultFor(field.kind);
      if (!provided || value[field.name] === defaultValue) continue;
    }
    const fieldValue = value[field.name];
    switch (field.kind) {
      case "string":
        chunks.push(encodeStringField(field.number, fieldValue));
        break;
      case "int32":
        chunks.push(encodeInt32Field(field.number, fieldValue));
        break;
      case "int64":
        chunks.push(encodeInt64Field(field.number, fieldValue));
        break;
      default:
        throw new WireError(`unsupported_field_kind:${field.kind}`);
    }
  }
  return Buffer.concat(chunks);
}

function skipField(buffer, offset, wireType, fieldNumber) {
  switch (wireType) {
    case 0:
      return decodeVarint(buffer, offset).offset;
    case 1:
      if (offset + 8 > buffer.length) throw new WireError("truncated_fixed64");
      return offset + 8;
    case 2: {
      const length = decodeVarint(buffer, offset);
      const end = length.offset + Number(length.value);
      if (end > buffer.length) throw new WireError("truncated_length_delimited_field");
      return end;
    }
    case 5:
      if (offset + 4 > buffer.length) throw new WireError("truncated_fixed32");
      return offset + 4;
    default:
      throw new WireError(`unsupported_wire_type:${wireType}_for_field:${fieldNumber}`);
  }
}

function decodeMessage(type, buffer) {
  if (!Buffer.isBuffer(buffer)) throw new WireError("message_must_be_a_buffer");
  const definition = definitionFor(type);
  const byNumber = new Map(definition.map((field) => [field.number, field]));
  const result = {};
  for (const field of definition) {
    if (field.optional !== true) result[field.name] = defaultFor(field.kind);
  }

  let offset = 0;
  while (offset < buffer.length) {
    const tag = decodeVarint(buffer, offset);
    offset = tag.offset;
    const fieldNumber = Number(tag.value >> 3n);
    const wireType = Number(tag.value & 0x7n);
    if (fieldNumber === 0) throw new WireError("invalid_field_number");

    const field = byNumber.get(fieldNumber);
    if (field === undefined) {
      offset = skipField(buffer, offset, wireType, fieldNumber);
      continue;
    }
    if (wireType !== wireTypeFor(field.kind)) {
      throw new WireError(`unexpected_wire_type:${wireType}_for_field:${fieldNumber}`);
    }

    if (wireType === 0) {
      const decoded = decodeVarint(buffer, offset);
      offset = decoded.offset;
      result[field.name] = convertVarint(field.kind, decoded.value);
    } else {
      const decoded = decodeVarint(buffer, offset);
      offset = decoded.offset;
      const length = Number(decoded.value);
      if (offset + length > buffer.length) throw new WireError("truncated_length_delimited_field");
      const bytes = buffer.subarray(offset, offset + length);
      offset += length;
      if (field.kind !== "string") throw new WireError(`unsupported_length_delimited_kind:${field.kind}`);
      result[field.name] = bytes.toString("utf8");
    }
  }
  return result;
}

/** Encode one gRPC message frame. Compression is not supported (flag 0). */
function encodeFrame(message) {
  const payload = Buffer.isBuffer(message) ? message : Buffer.from(message);
  if (payload.length > 0xffffffff) throw new WireError("message_too_large");
  const frame = Buffer.allocUnsafe(FRAME_HEADER_BYTES + payload.length);
  frame[0] = 0;
  frame.writeUInt32BE(payload.length, 1);
  payload.copy(frame, FRAME_HEADER_BYTES);
  return frame;
}

/** Incremental parser for a stream of gRPC frames. */
class FrameDecoder {
  constructor(options = {}) {
    this.maxMessageBytes = options.maxMessageBytes ?? DEFAULT_MAX_MESSAGE_BYTES;
    this.buffer = Buffer.alloc(0);
  }

  get pendingBytes() {
    return this.buffer.length;
  }

  push(chunk) {
    if (!Buffer.isBuffer(chunk)) chunk = Buffer.from(chunk);
    if (chunk.length === 0) return [];
    this.buffer = this.buffer.length === 0 ? chunk : Buffer.concat([this.buffer, chunk]);

    const messages = [];
    while (this.buffer.length >= FRAME_HEADER_BYTES) {
      const compressed = this.buffer[0];
      if (compressed !== 0) throw new WireError("compressed_frames_unsupported");
      const length = this.buffer.readUInt32BE(1);
      if (length > this.maxMessageBytes) throw new WireError("frame_too_large");
      if (this.buffer.length < FRAME_HEADER_BYTES + length) break;
      messages.push(this.buffer.subarray(FRAME_HEADER_BYTES, FRAME_HEADER_BYTES + length));
      this.buffer = this.buffer.subarray(FRAME_HEADER_BYTES + length);
    }
    return messages;
  }

  finish() {
    if (this.buffer.length !== 0) throw new WireError("truncated_frame");
  }
}

/** Decode a complete buffer that must contain exactly one gRPC frame. */
function decodeFrame(buffer) {
  const decoder = new FrameDecoder();
  const messages = decoder.push(buffer);
  decoder.finish();
  if (messages.length !== 1) throw new WireError("expected_one_frame");
  return messages[0];
}

/** Decode a complete buffer that may contain any number of gRPC frames. */
function decodeFrames(buffer) {
  const decoder = new FrameDecoder();
  const messages = decoder.push(buffer);
  decoder.finish();
  return messages;
}

function encodeGetReadingRequest(value) {
  return encodeMessage("GetReadingRequest", value);
}

function decodeGetReadingRequest(buffer) {
  return decodeMessage("GetReadingRequest", buffer);
}

function encodeStreamReadingsRequest(value) {
  return encodeMessage("StreamReadingsRequest", value);
}

function decodeStreamReadingsRequest(buffer) {
  return decodeMessage("StreamReadingsRequest", buffer);
}

function encodeReading(value) {
  return encodeMessage("Reading", value);
}

function decodeReading(buffer) {
  return decodeMessage("Reading", buffer);
}

module.exports = {
  FRAME_HEADER_BYTES,
  DEFAULT_MAX_MESSAGE_BYTES,
  FrameDecoder,
  MESSAGE_DEFINITIONS,
  WireError,
  encodeVarint,
  decodeVarint,
  encodeFrame,
  decodeFrame,
  decodeFrames,
  encodeMessage,
  decodeMessage,
  encodeGetReadingRequest,
  decodeGetReadingRequest,
  encodeStreamReadingsRequest,
  decodeStreamReadingsRequest,
  encodeReading,
  decodeReading,
};

"use strict";

/**
 * Minimal gRPC server over Node's built-in HTTP/2.
 *
 * Served methods (see proto/energy.proto):
 *   POST /energy.v1.EnergyService/GetReading
 *   POST /energy.v1.EnergyService/StreamReadings
 *
 * Responses use `content-type: application/grpc` and finish with a
 * `grpc-status` trailer. Errors are sent as a normal gRPC response with no
 * message frames and a non-zero status, so the client's error text stays
 * compatible with the REST baseline (`unknown_site`, `invalid_limit`).
 */

const http2 = require("node:http2");

const { readingFor, readingsFor } = require("./data.js");
const wire = require("./wire.js");

const SERVICE_PREFIX = "/energy.v1.EnergyService";
const PATHS = Object.freeze({
  getReading: `${SERVICE_PREFIX}/GetReading`,
  streamReadings: `${SERVICE_PREFIX}/StreamReadings`,
});

const GRPC_STATUS = Object.freeze({
  OK: 0,
  INVALID_ARGUMENT: 3,
  NOT_FOUND: 5,
  RESOURCE_EXHAUSTED: 8,
  UNIMPLEMENTED: 12,
  INTERNAL: 13,
});

const MAX_REQUEST_BYTES = 4 * 1024 * 1024;

class GrpcError extends Error {
  constructor(status, message) {
    super(message);
    this.name = "GrpcError";
    this.grpcStatus = status;
  }
}

function encodeGrpcMessage(message) {
  // gRPC defines grpc-message as percent-encoded UTF-8.
  return encodeURIComponent(message);
}

function sendTrailers(stream, status, message) {
  if (stream.destroyed) return;
  const trailers = { "grpc-status": String(status) };
  if (message !== undefined) trailers["grpc-message"] = encodeGrpcMessage(message);
  stream.sendTrailers(trailers);
}

/**
 * Send one complete gRPC response: initial headers, zero or more message
 * frames, then the terminal status trailer.
 */
function respond(stream, payloads, status, message) {
  if (stream.destroyed || stream.closed) return;
  if (stream.headersSent) {
    // A response is already underway; do not try to write a second one.
    stream.end();
    return;
  }
  stream.respond(
    { ":status": 200, "content-type": "application/grpc" },
    { waitForTrailers: true },
  );
  stream.once("wantTrailers", () => sendTrailers(stream, status, message));
  for (const payload of payloads) stream.write(wire.encodeFrame(payload));
  stream.end();
}

function readRequestBody(stream) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    let settled = false;

    const fail = (error) => {
      if (settled) return;
      settled = true;
      reject(error);
    };

    stream.on("data", (chunk) => {
      if (settled) return;
      size += chunk.length;
      if (size > MAX_REQUEST_BYTES) {
        fail(new GrpcError(GRPC_STATUS.RESOURCE_EXHAUSTED, "request_too_large"));
        stream.close(http2.constants.NGHTTP2_CANCEL);
        return;
      }
      chunks.push(chunk);
    });
    stream.on("end", () => {
      if (settled) return;
      settled = true;
      resolve(Buffer.concat(chunks));
    });
    stream.on("aborted", () => fail(new GrpcError(GRPC_STATUS.INTERNAL, "request_aborted")));
    stream.on("error", fail);
  });
}

function singleRequest(payloads) {
  if (payloads.length !== 1) throw new GrpcError(GRPC_STATUS.INVALID_ARGUMENT, "invalid_request");
  return payloads[0];
}

async function handleStream(stream, headers) {
  // Client resets are normal; keep them from becoming unhandled errors.
  stream.on("error", () => {});

  try {
    if (headers[":method"] !== "POST") {
      throw new GrpcError(GRPC_STATUS.UNIMPLEMENTED, "unimplemented");
    }
    const path = headers[":path"];
    if (path !== PATHS.getReading && path !== PATHS.streamReadings) {
      throw new GrpcError(GRPC_STATUS.UNIMPLEMENTED, "unimplemented");
    }
    const contentType = headers["content-type"];
    if (typeof contentType !== "string" || !contentType.startsWith("application/grpc")) {
      throw new GrpcError(GRPC_STATUS.UNIMPLEMENTED, "unsupported_content_type");
    }

    const body = await readRequestBody(stream);
    const message = singleRequest(wire.decodeFrames(body));

    if (path === PATHS.getReading) {
      const request = wire.decodeGetReadingRequest(message);
      const reading = readingFor(request.siteId);
      if (reading === null) throw new GrpcError(GRPC_STATUS.NOT_FOUND, "unknown_site");
      respond(stream, [wire.encodeReading(reading)], GRPC_STATUS.OK);
      return;
    }

    const request = wire.decodeStreamReadingsRequest(message);
    const readings = readingsFor(request.siteId);
    if (readings === null) throw new GrpcError(GRPC_STATUS.NOT_FOUND, "unknown_site");
    let selected = readings;
    if (request.limit !== undefined) {
      if (!Number.isInteger(request.limit) || request.limit < 0) {
        throw new GrpcError(GRPC_STATUS.INVALID_ARGUMENT, "invalid_limit");
      }
      selected = readings.slice(0, request.limit);
    }
    respond(stream, selected.map((reading) => wire.encodeReading(reading)), GRPC_STATUS.OK);
  } catch (error) {
    if (error instanceof GrpcError) {
      respond(stream, [], error.grpcStatus, error.message);
    } else if (error instanceof wire.WireError) {
      respond(stream, [], GRPC_STATUS.INVALID_ARGUMENT, "invalid_message");
    } else {
      respond(stream, [], GRPC_STATUS.INTERNAL, "internal");
    }
  }
}

function createGrpcServer() {
  const server = http2.createServer();
  server.on("stream", (stream, headers) => {
    void handleStream(stream, headers);
  });
  return server;
}

module.exports = {
  GRPC_STATUS,
  PATHS,
  GrpcError,
  createGrpcServer,
};

"use strict";

/**
 * The gRPC client for the fleet console.
 *
 * It returns the same plain objects as the REST client (`{ siteId, watts,
 * atMs }`) and rejects with the server's error text, so callers can switch
 * transports without changing their logic. `getReadings` is a convenience
 * collector over the server-streaming `StreamReadings` method.
 *
 * A connection is opened per call and always closed when the call completes,
 * which keeps short-lived processes (including `node --test`) from hanging on
 * an idle HTTP/2 session.
 */

const http2 = require("node:http2");

const wire = require("./wire.js");

const PATHS = Object.freeze({
  getReading: "/energy.v1.EnergyService/GetReading",
  streamReadings: "/energy.v1.EnergyService/StreamReadings",
});

const STATUS_NAMES = Object.freeze({
  0: "ok",
  1: "cancelled",
  2: "unknown",
  3: "invalid_argument",
  4: "deadline_exceeded",
  5: "not_found",
  6: "already_exists",
  7: "permission_denied",
  8: "resource_exhausted",
  9: "failed_precondition",
  10: "aborted",
  11: "out_of_range",
  12: "unimplemented",
  13: "internal",
  14: "unavailable",
  15: "data_loss",
  16: "unauthenticated",
});

const INT32_MIN = -2147483648;
const INT32_MAX = 2147483647;

class GrpcClientError extends Error {
  constructor(message, status) {
    super(message);
    this.name = "GrpcClientError";
    this.code = status;
    this.grpcStatus = status;
  }
}

function decodeGrpcMessage(value) {
  if (value === undefined) return undefined;
  try {
    return decodeURIComponent(String(value));
  } catch {
    return String(value);
  }
}

function extractStatus(headers, trailers) {
  const trailerStatus = trailers?.["grpc-status"];
  const headerStatus = headers?.["grpc-status"];
  const raw = trailerStatus ?? headerStatus;
  if (raw === undefined) return null;
  const status = Number(raw);
  if (!Number.isInteger(status) || status < 0) return null;
  const message = decodeGrpcMessage(
    trailers?.["grpc-message"] ?? headers?.["grpc-message"] ?? STATUS_NAMES[status] ?? `grpc_${status}`,
  );
  return { status, message };
}

function statusError(status, message) {
  return new GrpcClientError(message ?? STATUS_NAMES[status.status] ?? `grpc_${status.status}`, status.status);
}

function validateLimit(limit) {
  if (limit === undefined) return;
  if (!Number.isInteger(limit) || limit < INT32_MIN || limit > INT32_MAX) {
    throw new Error("invalid_limit");
  }
}

/**
 * Perform one gRPC call and yield the protobuf payload of every response
 * message. The terminal gRPC status is checked after the stream ends; a
 * non-zero status rejects the iteration with its `grpc-message`.
 */
async function* call(port, path, requestMessage) {
  const session = http2.connect(`http://127.0.0.1:${port}`);
  let sessionError = null;
  session.on("error", (error) => {
    sessionError = error;
  });

  try {
    const stream = session.request({
      ":method": "POST",
      ":path": path,
      "content-type": "application/grpc",
      "te": "trailers",
      "grpc-accept-encoding": "identity",
    });

    let responseHeaders;
    let responseTrailers;
    stream.on("response", (headers) => {
      responseHeaders = headers;
    });
    stream.on("trailers", (trailers) => {
      responseTrailers = trailers;
    });

    const parser = new wire.FrameDecoder();
    stream.end(wire.encodeFrame(requestMessage));

    for await (const chunk of stream) {
      for (const payload of parser.push(chunk)) yield payload;
    }

    if (sessionError !== null) throw sessionError;
    if (responseHeaders === undefined) throw new Error("missing_response_headers");

    const httpStatus = Number(responseHeaders[":status"] ?? 0);
    if (httpStatus !== 200) throw new Error(`http_${String(httpStatus)}`);
    const contentType = responseHeaders["content-type"];
    if (typeof contentType !== "string" || !contentType.startsWith("application/grpc")) {
      throw new Error("invalid_content_type");
    }

    const status = extractStatus(responseHeaders, responseTrailers);
    if (status === null) throw new Error("missing_grpc_status");
    if (status.status !== 0) throw statusError(status);
    parser.finish();
  } finally {
    if (!session.destroyed && !session.closed) session.close();
  }
}

function createGrpcClient(port, options = {}) {
  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    throw new TypeError("port must be an integer between 0 and 65535");
  }
  if (options.host !== undefined && options.host !== "127.0.0.1") {
    throw new TypeError("only the loopback host is supported");
  }

  async function getReading(siteId) {
    const messages = [];
    for await (const payload of call(
      port,
      PATHS.getReading,
      wire.encodeGetReadingRequest({ siteId }),
    )) {
      messages.push(payload);
    }
    if (messages.length !== 1) throw new Error("invalid_response");
    return wire.decodeReading(messages[0]);
  }

  function streamReadings(siteId, limit) {
    return (async function* stream() {
      validateLimit(limit);
      const request = wire.encodeStreamReadingsRequest({ siteId, limit });
      for await (const payload of call(port, PATHS.streamReadings, request)) {
        yield wire.decodeReading(payload);
      }
    })();
  }

  async function getReadings(siteId, limit) {
    const readings = [];
    for await (const reading of streamReadings(siteId, limit)) readings.push(reading);
    return readings;
  }

  return {
    getReading,
    getReadings,
    streamReadings,
    // Connections are per-call; close() exists so a long-lived console can
    // release the client in the same way it would release a session-backed
    // client.
    close() {},
  };
}

module.exports = {
  PATHS,
  GrpcClientError,
  createGrpcClient,
};

"use strict";

/**
 * Server-level tests. These speak the gRPC wire protocol directly over
 * node:http2 so they prove the framing, headers, trailers, and status mapping
 * independently of the client wrapper.
 */
const assert = require("node:assert/strict");
const http2 = require("node:http2");
const { after, before, test } = require("node:test");

const { createGrpcServer, PATHS } = require("../service/grpc_server.js");
const wire = require("../service/wire.js");

let server;
let port;

before(async () => {
  server = createGrpcServer();
  await new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  });
  port = server.address().port;
});

after(async () => {
  await new Promise((resolve) => server.close(resolve));
});

function rawCall(path, requestFrame) {
  return new Promise((resolve, reject) => {
    const session = http2.connect(`http://127.0.0.1:${port}`);
    const result = { headers: null, trailers: null, messages: [], body: null };
    let settled = false;

    const finish = (error) => {
      if (settled) return;
      settled = true;
      if (!session.destroyed && !session.closed) session.close();
      if (error !== undefined) reject(error);
      else resolve(result);
    };

    session.on("error", finish);
    const stream = session.request({
      ":method": "POST",
      ":path": path,
      "content-type": "application/grpc",
      "te": "trailers",
    });
    stream.on("response", (headers) => {
      result.headers = headers;
    });
    stream.on("trailers", (trailers) => {
      result.trailers = trailers;
    });
    stream.on("data", (chunk) => {
      result.body = result.body === null ? chunk : Buffer.concat([result.body, chunk]);
    });
    stream.on("end", () => {
      try {
        const decoder = new wire.FrameDecoder();
        result.messages = decoder.push(result.body ?? Buffer.alloc(0));
        decoder.finish();
      } catch (error) {
        finish(error);
        return;
      }
      finish();
    });
    stream.on("error", finish);
    stream.end(requestFrame);
  });
}

test("gRPC frame is a compressed flag plus a big-endian length", () => {
  const frame = wire.encodeFrame(Buffer.from([0x08, 0x01]));
  assert.deepEqual([...frame], [0, 0, 0, 0, 2, 0x08, 0x01]);
  assert.deepEqual([...wire.decodeFrame(frame)], [0x08, 0x01]);
});

test("the incremental frame decoder accepts a frame split across chunks", () => {
  const payload = Buffer.from([0x08, 0x01]);
  const frame = wire.encodeFrame(payload);
  const decoder = new wire.FrameDecoder();
  assert.deepEqual(decoder.push(frame.subarray(0, 3)), []);
  assert.equal(decoder.pendingBytes, 3);
  assert.deepEqual(decoder.push(frame.subarray(3)), [payload]);
  decoder.finish();
});

test("reading messages round-trip with exact field numbers and values", () => {
  const reading = { siteId: "site-a", watts: 4120, atMs: 1762300000000 };
  const encoded = wire.encodeReading(reading);
  // field 1 (site_id), field 2 (watts), field 3 (at_ms)
  assert.equal(encoded[0], 0x0a);
  assert.match(encoded.toString("latin1"), /site-a/u);
  assert.deepEqual(wire.decodeReading(encoded), reading);
});

test("optional limit preserves absent versus explicit zero", () => {
  const absent = wire.decodeStreamReadingsRequest(
    wire.encodeStreamReadingsRequest({ siteId: "site-a" }),
  );
  assert.equal(absent.limit, undefined);

  const zero = wire.decodeStreamReadingsRequest(
    wire.encodeStreamReadingsRequest({ siteId: "site-a", limit: 0 }),
  );
  assert.equal(zero.limit, 0);
});

test("GetReading serves one framed Reading with grpc-status 0", async () => {
  const result = await rawCall(
    PATHS.getReading,
    wire.encodeFrame(wire.encodeGetReadingRequest({ siteId: "site-a" })),
  );

  assert.equal(result.headers[":status"], 200);
  assert.match(result.headers["content-type"], /^application\/grpc/u);
  assert.equal(result.trailers["grpc-status"], "0");
  assert.equal(result.messages.length, 1);
  assert.deepEqual(wire.decodeReading(result.messages[0]), {
    siteId: "site-a",
    watts: 4120,
    atMs: 1762300000000,
  });
});

test("StreamReadings preserves source order and honours limit", async () => {
  const result = await rawCall(
    PATHS.streamReadings,
    wire.encodeFrame(wire.encodeStreamReadingsRequest({ siteId: "site-a", limit: 3 })),
  );

  assert.equal(result.trailers["grpc-status"], "0");
  const readings = result.messages.map((message) => wire.decodeReading(message));
  assert.equal(readings.length, 3);
  assert.deepEqual(
    readings.map((reading) => reading.atMs),
    [1762300000000, 1762300060000, 1762300120000],
  );
});

test("StreamReadings without a limit sends every reading", async () => {
  const result = await rawCall(
    PATHS.streamReadings,
    wire.encodeFrame(wire.encodeStreamReadingsRequest({ siteId: "site-b" })),
  );

  assert.equal(result.trailers["grpc-status"], "0");
  assert.equal(result.messages.length, 3);
  assert.deepEqual(
    result.messages.map((message) => wire.decodeReading(message).siteId),
    ["site-b", "site-b", "site-b"],
  );
});

test("unknown sites return NOT_FOUND and never an empty stream", async () => {
  const result = await rawCall(
    PATHS.streamReadings,
    wire.encodeFrame(wire.encodeStreamReadingsRequest({ siteId: "site-zz" })),
  );

  assert.equal(result.trailers["grpc-status"], "5");
  assert.equal(decodeURIComponent(result.trailers["grpc-message"]), "unknown_site");
  assert.equal(result.messages.length, 0);
});

test("a negative limit returns INVALID_ARGUMENT invalid_limit", async () => {
  const result = await rawCall(
    PATHS.streamReadings,
    wire.encodeFrame(wire.encodeStreamReadingsRequest({ siteId: "site-a", limit: -1 })),
  );

  assert.equal(result.trailers["grpc-status"], "3");
  assert.equal(decodeURIComponent(result.trailers["grpc-message"]), "invalid_limit");
  assert.equal(result.messages.length, 0);
});

test("an unknown method returns UNIMPLEMENTED", async () => {
  const result = await rawCall(
    "/energy.v1.EnergyService/NoSuchMethod",
    wire.encodeFrame(Buffer.alloc(0)),
  );

  assert.equal(result.trailers["grpc-status"], "12");
  assert.equal(decodeURIComponent(result.trailers["grpc-message"]), "unimplemented");
});

"use strict";

/**
 * Integration tests: a real gRPC client talks to a real gRPC server, and the
 * same fixtures are compared with the REST console path that must keep
 * working. No mocks and no in-process shortcuts.
 */
const assert = require("node:assert/strict");
const { after, before, test } = require("node:test");

const { createGrpcClient } = require("../service/grpc_client.js");
const { createGrpcServer } = require("../service/grpc_server.js");
const { createRestClient } = require("../service/rest_client.js");
const { createRestServer } = require("../service/rest_server.js");

let grpcServer;
let restServer;
let grpc;
let rest;

async function listen(server) {
  await new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  });
  return server.address().port;
}

before(async () => {
  grpcServer = createGrpcServer();
  restServer = createRestServer();
  const [grpcPort, restPort] = await Promise.all([listen(grpcServer), listen(restServer)]);
  grpc = createGrpcClient(grpcPort);
  rest = createRestClient(restPort);
});

after(async () => {
  grpc.close();
  await Promise.all([
    new Promise((resolve) => grpcServer.close(resolve)),
    new Promise((resolve) => restServer.close(resolve)),
  ]);
});

test("GetReading returns the same values as the REST console for every site", async () => {
  for (const siteId of ["site-a", "site-b"]) {
    assert.deepEqual(await grpc.getReading(siteId), await rest.getReading(siteId));
  }
});

test("StreamReadings matches REST ordering and limit semantics", async () => {
  assert.deepEqual(await grpc.getReadings("site-a", 3), await rest.getReadings("site-a", 3));
  assert.deepEqual(await grpc.getReadings("site-a"), await rest.getReadings("site-a"));
  assert.deepEqual(await grpc.getReadings("site-a", 0), await rest.getReadings("site-a", 0));
  assert.deepEqual(await grpc.getReadings("site-a", 99), await rest.getReadings("site-a", 99));
});

test("atMs crosses the wire as the exact epoch millisecond integer", async () => {
  const readings = await grpc.getReadings("site-a");
  assert.deepEqual(
    readings.map((reading) => reading.atMs),
    [1762300000000, 1762300060000, 1762300120000, 1762300180000, 1762300240000, 1762300300000],
  );
  for (const reading of readings) {
    assert.equal(Number.isInteger(reading.atMs), true);
    assert.equal(Number.isInteger(reading.watts), true);
  }
});

test("streamReadings yields readings as a stream, not one batch", async () => {
  const seen = [];
  for await (const reading of grpc.streamReadings("site-b")) seen.push(reading);
  assert.deepEqual(seen, await grpc.getReadings("site-b"));
  assert.equal(seen.length, 3);
});

test("unknown sites reject with unknown_site, not an empty result", async () => {
  await assert.rejects(() => grpc.getReading("site-zz"), /unknown_site/u);
  await assert.rejects(() => grpc.getReadings("site-zz"), /unknown_site/u);
  await assert.rejects(() => rest.getReading("site-zz"), /unknown_site/u);
});

test("invalid limits reject with invalid_limit through the gRPC client", async () => {
  await assert.rejects(() => grpc.getReadings("site-a", -1), /invalid_limit/u);
  await assert.rejects(() => grpc.getReadings("site-a", 1.5), /invalid_limit/u);
  await assert.rejects(() => rest.getReadings("site-a", 1.5), /invalid_limit/u);
});

test("concurrent calls stay isolated and correct", async () => {
  const calls = [];
  for (let index = 0; index < 20; index += 1) {
    const siteId = index % 2 === 0 ? "site-a" : "site-b";
    calls.push(grpc.getReading(siteId));
  }
  const readings = await Promise.all(calls);
  for (const [index, reading] of readings.entries()) {
    assert.equal(reading.siteId, index % 2 === 0 ? "site-a" : "site-b");
    assert.equal(reading.atMs, 1762300000000);
  }
});

syntax = "proto3";

package energy.v1;

// The site-readings service. Field numbers in this file are part of the wire
// contract: once committed, they must not be reused or renumbered.
service EnergyService {
  // Returns the current (first) reading for one site.
  rpc GetReading(GetReadingRequest) returns (Reading);

  // Returns readings for one site in source order. The limit is optional;
  // when it is absent every reading is returned, and when it is present but
  // zero an empty stream is returned.
  rpc StreamReadings(StreamReadingsRequest) returns (stream Reading);
}

message GetReadingRequest {
  string site_id = 1;
}

message StreamReadingsRequest {
  string site_id = 1;

  // `optional` preserves field presence so "no limit" is distinguishable from
  // an explicit limit of zero. A negative value is rejected as invalid_limit.
  optional int32 limit = 2;
}

message Reading {
  string site_id = 1;
  int64 watts = 2;
  int64 at_ms = 3;
}

"use strict";

/**
 * Hand-written gRPC framing and protobuf codec.
 *
 * The deployment has no third-party packages, so this module implements only
 * the protobuf features used by proto/energy.proto:
 *
 *   - gRPC message framing: 1 compressed-flag byte + 4-byte big-endian length,
 *     followed by the protobuf message bytes;
 *   - protobuf varints, length-delimited strings, int32 and int64 fields;
 *   - tolerant decoding of unknown fields (they are skipped, as proto3
 *     requires).
 *
 * Message field numbers match proto/energy.proto and must stay in sync with it.
 */

const FRAME_HEADER_BYTES = 5;
const DEFAULT_MAX_MESSAGE_BYTES = 4 * 1024 * 1024;

class WireError extends Error {
  constructor(message) {
    super(message);
    this.name = "WireError";
    this.code = "wire";
  }
}

function assertSafeInteger(value, what) {
  if (typeof value !== "number" || !Number.isSafeInteger(value)) {
    throw new WireError(`${what}_must_be_a_safe_integer`);
  }
  return BigInt(value);
}

/** Encode an unsigned 64-bit varint (negative values use two's complement). */
function encodeVarint(value) {
  let remaining;
  if (typeof value === "bigint") {
    remaining = BigInt.asUintN(64, value);
  } else {
    remaining = BigInt.asUintN(64, assertSafeInteger(value, "varint"));
  }
  const bytes = [];
  do {
    let byte = Number(remaining & 0x7fn);
    remaining >>= 7n;
    if (remaining !== 0n) byte |= 0x80;
    bytes.push(byte);
  } while (remaining !== 0n);
  return Buffer.from(bytes);
}

/** Decode one unsigned 64-bit varint, returning its raw BigInt value. */
function decodeVarint(buffer, offset = 0) {
  let value = 0n;
  let shift = 0n;
  let index = offset;
  for (let count = 0; count < 10; count += 1) {
    if (index >= buffer.length) throw new WireError("truncated_varint");
    const byte = buffer[index];
    index += 1;
    value |= BigInt(byte & 0x7f) << shift;
    if ((byte & 0x80) === 0) return { value, offset: index };
    shift += 7n;
  }
  throw new WireError("varint_too_long");
}

function encodeTag(fieldNumber, wireType) {
  if (!Number.isInteger(fieldNumber) || fieldNumber < 1) {
    throw new WireError("invalid_field_number");
  }
  return encodeVarint((BigInt(fieldNumber) << 3n) | BigInt(wireType));
}

function encodeStringField(fieldNumber, value) {
  if (typeof value !== "string") throw new WireError("string_field_requires_a_string");
  const bytes = Buffer.from(value, "utf8");
  return Buffer.concat([encodeTag(fieldNumber, 2), encodeVarint(bytes.length), bytes]);
}

function encodeInt32Field(fieldNumber, value) {
  if (!Number.isInteger(value) || value < -2147483648 || value > 2147483647) {
    throw new WireError("int32_out_of_range");
  }
  // int32 values are sign-extended to a 64-bit varint on the wire.
  return Buffer.concat([encodeTag(fieldNumber, 0), encodeVarint(BigInt(value))]);
}

function encodeInt64Field(fieldNumber, value) {
  if (typeof value === "number") {
    if (!Number.isSafeInteger(value)) throw new WireError("int64_out_of_range");
  } else if (typeof value === "bigint") {
    if (value < -(1n << 63n) || value > (1n << 63n) - 1n) {
      throw new WireError("int64_out_of_range");
    }
  } else {
    throw new WireError("int64_out_of_range");
  }
  return Buffer.concat([encodeTag(fieldNumber, 0), encodeVarint(value)]);
}

function wireTypeFor(kind) {
  return kind === "string" ? 2 : 0;
}

function defaultFor(kind) {
  return kind === "string" ? "" : 0;
}

function convertVarint(kind, raw) {
  switch (kind) {
    case "int32":
      return Number(BigInt.asIntN(32, raw));
    case "int64":
      return Number(BigInt.asIntN(64, raw));
    default:
      throw new WireError("unsupported_varint_kind");
  }
}

/**
 * Field descriptors. These are the single source of truth for both enum and
 * decode; proto/energy.proto is the human-facing declaration of the same
 * contract.
 */
const MESSAGE_DEFINITIONS = Object.freeze({
  GetReadingRequest: Object.freeze([
    Object.freeze({ number: 1, name: "siteId", kind: "string" }),
  ]),
  StreamReadingsRequest: Object.freeze([
    Object.freeze({ number: 1, name: "siteId", kind: "string" }),
    Object.freeze({ number: 2, name: "limit", kind: "int32", optional: true }),
  ]),
  Reading: Object.freeze([
    Object.freeze({ number: 1, name: "siteId", kind: "string" }),
    Object.freeze({ number: 2, name: "watts", kind: "int64" }),
    Object.freeze({ number: 3, name: "atMs", kind: "int64" }),
  ]),
});

function definitionFor(type) {
  const definition = MESSAGE_DEFINITIONS[type];
  if (definition === undefined) throw new WireError(`unknown_message_type:${type}`);
  return definition;
}

function encodeMessage(type, value) {
  if (value === null || typeof value !== "object") {
    throw new WireError(`${type}_must_be_an_object`);
  }
  const chunks = [];
  for (const field of definitionFor(type)) {
    const provided = Object.prototype.hasOwnProperty.call(value, field.name) && value[field.name] !== undefined;
    if (field.optional === true) {
      // Presence matters for optional fields: an explicit zero must be encoded.
      if (!provided) continue;
    } else {
      const defaultValue = defaultFor(field.kind);
      if (!provided || value[field.name] === defaultValue) continue;
    }
    const fieldValue = value[field.name];
    switch (field.kind) {
      case "string":
        chunks.push(encodeStringField(field.number, fieldValue));
        break;
      case "int32":
        chunks.push(encodeInt32Field(field.number, fieldValue));
        break;
      case "int64":
        chunks.push(encodeInt64Field(field.number, fieldValue));
        break;
      default:
        throw new WireError(`unsupported_field_kind:${field.kind}`);
    }
  }
  return Buffer.concat(chunks);
}

function skipField(buffer, offset, wireType, fieldNumber) {
  switch (wireType) {
    case 0:
      return decodeVarint(buffer, offset).offset;
    case 1:
      if (offset + 8 > buffer.length) throw new WireError("truncated_fixed64");
      return offset + 8;
    case 2: {
      const length = decodeVarint(buffer, offset);
      const end = length.offset + Number(length.value);
      if (end > buffer.length) throw new WireError("truncated_length_delimited_field");
      return end;
    }
    case 5:
      if (offset + 4 > buffer.length) throw new WireError("truncated_fixed32");
      return offset + 4;
    default:
      throw new WireError(`unsupported_wire_type:${wireType}_for_field:${fieldNumber}`);
  }
}

function decodeMessage(type, buffer) {
  if (!Buffer.isBuffer(buffer)) throw new WireError("message_must_be_a_buffer");
  const definition = definitionFor(type);
  const byNumber = new Map(definition.map((field) => [field.number, field]));
  const result = {};
  for (const field of definition) {
    if (field.optional !== true) result[field.name] = defaultFor(field.kind);
  }

  let offset = 0;
  while (offset < buffer.length) {
    const tag = decodeVarint(buffer, offset);
    offset = tag.offset;
    const fieldNumber = Number(tag.value >> 3n);
    const wireType = Number(tag.value & 0x7n);
    if (fieldNumber === 0) throw new WireError("invalid_field_number");

    const field = byNumber.get(fieldNumber);
    if (field === undefined) {
      offset = skipField(buffer, offset, wireType, fieldNumber);
      continue;
    }
    if (wireType !== wireTypeFor(field.kind)) {
      throw new WireError(`unexpected_wire_type:${wireType}_for_field:${fieldNumber}`);
    }

    if (wireType === 0) {
      const decoded = decodeVarint(buffer, offset);
      offset = decoded.offset;
      result[field.name] = convertVarint(field.kind, decoded.value);
    } else {
      const decoded = decodeVarint(buffer, offset);
      offset = decoded.offset;
      const length = Number(decoded.value);
      if (offset + length > buffer.length) throw new WireError("truncated_length_delimited_field");
      const bytes = buffer.subarray(offset, offset + length);
      offset += length;
      if (field.kind !== "string") throw new WireError(`unsupported_length_delimited_kind:${field.kind}`);
      result[field.name] = bytes.toString("utf8");
    }
  }
  return result;
}

/** Encode one gRPC message frame. Compression is not supported (flag 0). */
function encodeFrame(message) {
  const payload = Buffer.isBuffer(message) ? message : Buffer.from(message);
  if (payload.length > 0xffffffff) throw new WireError("message_too_large");
  const frame = Buffer.allocUnsafe(FRAME_HEADER_BYTES + payload.length);
  frame[0] = 0;
  frame.writeUInt32BE(payload.length, 1);
  payload.copy(frame, FRAME_HEADER_BYTES);
  return frame;
}

/** Incremental parser for a stream of gRPC frames. */
class FrameDecoder {
  constructor(options = {}) {
    this.maxMessageBytes = options.maxMessageBytes ?? DEFAULT_MAX_MESSAGE_BYTES;
    this.buffer = Buffer.alloc(0);
  }

  get pendingBytes() {
    return this.buffer.length;
  }

  push(chunk) {
    if (!Buffer.isBuffer(chunk)) chunk = Buffer.from(chunk);
    if (chunk.length === 0) return [];
    this.buffer = this.buffer.length === 0 ? chunk : Buffer.concat([this.buffer, chunk]);

    const messages = [];
    while (this.buffer.length >= FRAME_HEADER_BYTES) {
      const compressed = this.buffer[0];
      if (compressed !== 0) throw new WireError("compressed_frames_unsupported");
      const length = this.buffer.readUInt32BE(1);
      if (length > this.maxMessageBytes) throw new WireError("frame_too_large");
      if (this.buffer.length < FRAME_HEADER_BYTES + length) break;
      messages.push(this.buffer.subarray(FRAME_HEADER_BYTES, FRAME_HEADER_BYTES + length));
      this.buffer = this.buffer.subarray(FRAME_HEADER_BYTES + length);
    }
    return messages;
  }

  finish() {
    if (this.buffer.length !== 0) throw new WireError("truncated_frame");
  }
}

/** Decode a complete buffer that must contain exactly one gRPC frame. */
function decodeFrame(buffer) {
  const decoder = new FrameDecoder();
  const messages = decoder.push(buffer);
  decoder.finish();
  if (messages.length !== 1) throw new WireError("expected_one_frame");
  return messages[0];
}

/** Decode a complete buffer that may contain any number of gRPC frames. */
function decodeFrames(buffer) {
  const decoder = new FrameDecoder();
  const messages = decoder.push(buffer);
  decoder.finish();
  return messages;
}

function encodeGetReadingRequest(value) {
  return encodeMessage("GetReadingRequest", value);
}

function decodeGetReadingRequest(buffer) {
  return decodeMessage("GetReadingRequest", buffer);
}

function encodeStreamReadingsRequest(value) {
  return encodeMessage("StreamReadingsRequest", value);
}

function decodeStreamReadingsRequest(buffer) {
  return decodeMessage("StreamReadingsRequest", buffer);
}

function encodeReading(value) {
  return encodeMessage("Reading", value);
}

function decodeReading(buffer) {
  return decodeMessage("Reading", buffer);
}

module.exports = {
  FRAME_HEADER_BYTES,
  DEFAULT_MAX_MESSAGE_BYTES,
  FrameDecoder,
  MESSAGE_DEFINITIONS,
  WireError,
  encodeVarint,
  decodeVarint,
  encodeFrame,
  decodeFrame,
  decodeFrames,
  encodeMessage,
  decodeMessage,
  encodeGetReadingRequest,
  decodeGetReadingRequest,
  encodeStreamReadingsRequest,
  decodeStreamReadingsRequest,
  encodeReading,
  decodeReading,
};

"use strict";

/**
 * Minimal gRPC server over Node's built-in HTTP/2.
 *
 * Served methods (see proto/energy.proto):
 *   POST /energy.v1.EnergyService/GetReading
 *   POST /energy.v1.EnergyService/StreamReadings
 *
 * Responses use `content-type: application/grpc` and finish with a
 * `grpc-status` trailer. Errors are sent as a normal gRPC response with no
 * message frames and a non-zero status, so the client's error text stays
 * compatible with the REST baseline (`unknown_site`, `invalid_limit`).
 */

const http2 = require("node:http2");

const { readingFor, readingsFor } = require("./data.js");
const wire = require("./wire.js");

const SERVICE_PREFIX = "/energy.v1.EnergyService";
const PATHS = Object.freeze({
  getReading: `${SERVICE_PREFIX}/GetReading`,
  streamReadings: `${SERVICE_PREFIX}/StreamReadings`,
});

const GRPC_STATUS = Object.freeze({
  OK: 0,
  INVALID_ARGUMENT: 3,
  NOT_FOUND: 5,
  RESOURCE_EXHAUSTED: 8,
  UNIMPLEMENTED: 12,
  INTERNAL: 13,
});

const MAX_REQUEST_BYTES = 4 * 1024 * 1024;

class GrpcError extends Error {
  constructor(status, message) {
    super(message);
    this.name = "GrpcError";
    this.grpcStatus = status;
  }
}

function encodeGrpcMessage(message) {
  // gRPC defines grpc-message as percent-encoded UTF-8.
  return encodeURIComponent(message);
}

function sendTrailers(stream, status, message) {
  if (stream.destroyed) return;
  const trailers = { "grpc-status": String(status) };
  if (message !== undefined) trailers["grpc-message"] = encodeGrpcMessage(message);
  stream.sendTrailers(trailers);
}

/**
 * Send one complete gRPC response: initial headers, zero or more message
 * frames, then the terminal status trailer.
 */
function respond(stream, payloads, status, message) {
  if (stream.destroyed || stream.closed) return;
  if (stream.headersSent) {
    // A response is already underway; do not try to write a second one.
    stream.end();
    return;
  }
  stream.respond(
    { ":status": 200, "content-type": "application/grpc" },
    { waitForTrailers: true },
  );
  stream.once("wantTrailers", () => sendTrailers(stream, status, message));
  for (const payload of payloads) stream.write(wire.encodeFrame(payload));
  stream.end();
}

function readRequestBody(stream) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    let settled = false;

    const fail = (error) => {
      if (settled) return;
      settled = true;
      reject(error);
    };

    stream.on("data", (chunk) => {
      if (settled) return;
      size += chunk.length;
      if (size > MAX_REQUEST_BYTES) {
        fail(new GrpcError(GRPC_STATUS.RESOURCE_EXHAUSTED, "request_too_large"));
        stream.close(http2.constants.NGHTTP2_CANCEL);
        return;
      }
      chunks.push(chunk);
    });
    stream.on("end", () => {
      if (settled) return;
      settled = true;
      resolve(Buffer.concat(chunks));
    });
    stream.on("aborted", () => fail(new GrpcError(GRPC_STATUS.INTERNAL, "request_aborted")));
    stream.on("error", fail);
  });
}

function singleRequest(payloads) {
  if (payloads.length !== 1) throw new GrpcError(GRPC_STATUS.INVALID_ARGUMENT, "invalid_request");
  return payloads[0];
}

async function handleStream(stream, headers) {
  // Client resets are normal; keep them from becoming unhandled errors.
  stream.on("error", () => {});

  try {
    if (headers[":method"] !== "POST") {
      throw new GrpcError(GRPC_STATUS.UNIMPLEMENTED, "unimplemented");
    }
    const path = headers[":path"];
    if (path !== PATHS.getReading && path !== PATHS.streamReadings) {
      throw new GrpcError(GRPC_STATUS.UNIMPLEMENTED, "unimplemented");
    }
    const contentType = headers["content-type"];
    if (typeof contentType !== "string" || !contentType.startsWith("application/grpc")) {
      throw new GrpcError(GRPC_STATUS.UNIMPLEMENTED, "unsupported_content_type");
    }

    const body = await readRequestBody(stream);
    const message = singleRequest(wire.decodeFrames(body));

    if (path === PATHS.getReading) {
      const request = wire.decodeGetReadingRequest(message);
      const reading = readingFor(request.siteId);
      if (reading === null) throw new GrpcError(GRPC_STATUS.NOT_FOUND, "unknown_site");
      respond(stream, [wire.encodeReading(reading)], GRPC_STATUS.OK);
      return;
    }

    const request = wire.decodeStreamReadingsRequest(message);
    const readings = readingsFor(request.siteId);
    if (readings === null) throw new GrpcError(GRPC_STATUS.NOT_FOUND, "unknown_site");
    let selected = readings;
    if (request.limit !== undefined) {
      if (!Number.isInteger(request.limit) || request.limit < 0) {
        throw new GrpcError(GRPC_STATUS.INVALID_ARGUMENT, "invalid_limit");
      }
      selected = readings.slice(0, request.limit);
    }
    respond(stream, selected.map((reading) => wire.encodeReading(reading)), GRPC_STATUS.OK);
  } catch (error) {
    if (error instanceof GrpcError) {
      respond(stream, [], error.grpcStatus, error.message);
    } else if (error instanceof wire.WireError) {
      respond(stream, [], GRPC_STATUS.INVALID_ARGUMENT, "invalid_message");
    } else {
      respond(stream, [], GRPC_STATUS.INTERNAL, "internal");
    }
  }
}

function createGrpcServer() {
  const server = http2.createServer();
  server.on("stream", (stream, headers) => {
    void handleStream(stream, headers);
  });
  return server;
}

module.exports = {
  GRPC_STATUS,
  PATHS,
  GrpcError,
  createGrpcServer,
};

"use strict";

/**
 * The gRPC client for the fleet console.
 *
 * It returns the same plain objects as the REST client (`{ siteId, watts,
 * atMs }`) and rejects with the server's error text, so callers can switch
 * transports without changing their logic. `getReadings` is a convenience
 * collector over the server-streaming `StreamReadings` method.
 *
 * A connection is opened per call and always closed when the call completes,
 * which keeps short-lived processes (including `node --test`) from hanging on
 * an idle HTTP/2 session.
 */

const http2 = require("node:http2");

const wire = require("./wire.js");

const PATHS = Object.freeze({
  getReading: "/energy.v1.EnergyService/GetReading",
  streamReadings: "/energy.v1.EnergyService/StreamReadings",
});

const STATUS_NAMES = Object.freeze({
  0: "ok",
  1: "cancelled",
  2: "unknown",
  3: "invalid_argument",
  4: "deadline_exceeded",
  5: "not_found",
  6: "already_exists",
  7: "permission_denied",
  8: "resource_exhausted",
  9: "failed_precondition",
  10: "aborted",
  11: "out_of_range",
  12: "unimplemented",
  13: "internal",
  14: "unavailable",
  15: "data_loss",
  16: "unauthenticated",
});

const INT32_MIN = -2147483648;
const INT32_MAX = 2147483647;

class GrpcClientError extends Error {
  constructor(message, status) {
    super(message);
    this.name = "GrpcClientError";
    this.code = status;
    this.grpcStatus = status;
  }
}

function decodeGrpcMessage(value) {
  if (value === undefined) return undefined;
  try {
    return decodeURIComponent(String(value));
  } catch {
    return String(value);
  }
}

function extractStatus(headers, trailers) {
  const trailerStatus = trailers?.["grpc-status"];
  const headerStatus = headers?.["grpc-status"];
  const raw = trailerStatus ?? headerStatus;
  if (raw === undefined) return null;
  const status = Number(raw);
  if (!Number.isInteger(status) || status < 0) return null;
  const message = decodeGrpcMessage(
    trailers?.["grpc-message"] ?? headers?.["grpc-message"] ?? STATUS_NAMES[status] ?? `grpc_${status}`,
  );
  return { status, message };
}

function statusError(status, message) {
  return new GrpcClientError(message ?? STATUS_NAMES[status.status] ?? `grpc_${status.status}`, status.status);
}

function validateLimit(limit) {
  if (limit === undefined) return;
  if (!Number.isInteger(limit) || limit < INT32_MIN || limit > INT32_MAX) {
    throw new Error("invalid_limit");
  }
}

/**
 * Perform one gRPC call and yield the protobuf payload of every response
 * message. The terminal gRPC status is checked after the stream ends; a
 * non-zero status rejects the iteration with its `grpc-message`.
 */
async function* call(port, path, requestMessage) {
  const session = http2.connect(`http://127.0.0.1:${port}`);
  let sessionError = null;
  session.on("error", (error) => {
    sessionError = error;
  });

  try {
    const stream = session.request({
      ":method": "POST",
      ":path": path,
      "content-type": "application/grpc",
      "te": "trailers",
      "grpc-accept-encoding": "identity",
    });

    let responseHeaders;
    let responseTrailers;
    stream.on("response", (headers) => {
      responseHeaders = headers;
    });
    stream.on("trailers", (trailers) => {
      responseTrailers = trailers;
    });

    const parser = new wire.FrameDecoder();
    stream.end(wire.encodeFrame(requestMessage));

    for await (const chunk of stream) {
      for (const payload of parser.push(chunk)) yield payload;
    }

    if (sessionError !== null) throw sessionError;
    if (responseHeaders === undefined) throw new Error("missing_response_headers");

    const httpStatus = Number(responseHeaders[":status"] ?? 0);
    if (httpStatus !== 200) throw new Error(`http_${String(httpStatus)}`);
    const contentType = responseHeaders["content-type"];
    if (typeof contentType !== "string" || !contentType.startsWith("application/grpc")) {
      throw new Error("invalid_content_type");
    }

    const status = extractStatus(responseHeaders, responseTrailers);
    if (status === null) throw new Error("missing_grpc_status");
    if (status.status !== 0) throw statusError(status);
    parser.finish();
  } finally {
    if (!session.destroyed && !session.closed) session.close();
  }
}

function createGrpcClient(port, options = {}) {
  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    throw new TypeError("port must be an integer between 0 and 65535");
  }
  if (options.host !== undefined && options.host !== "127.0.0.1") {
    throw new TypeError("only the loopback host is supported");
  }

  async function getReading(siteId) {
    const messages = [];
    for await (const payload of call(
      port,
      PATHS.getReading,
      wire.encodeGetReadingRequest({ siteId }),
    )) {
      messages.push(payload);
    }
    if (messages.length !== 1) throw new Error("invalid_response");
    return wire.decodeReading(messages[0]);
  }

  function streamReadings(siteId, limit) {
    return (async function* stream() {
      validateLimit(limit);
      const request = wire.encodeStreamReadingsRequest({ siteId, limit });
      for await (const payload of call(port, PATHS.streamReadings, request)) {
        yield wire.decodeReading(payload);
      }
    })();
  }

  async function getReadings(siteId, limit) {
    const readings = [];
    for await (const reading of streamReadings(siteId, limit)) readings.push(reading);
    return readings;
  }

  return {
    getReading,
    getReadings,
    streamReadings,
    // Connections are per-call; close() exists so a long-lived console can
    // release the client in the same way it would release a session-backed
    // client.
    close() {},
  };
}

module.exports = {
  PATHS,
  GrpcClientError,
  createGrpcClient,
};

"use strict";

/**
 * Server-level tests. These speak the gRPC wire protocol directly over
 * node:http2 so they prove the framing, headers, trailers, and status mapping
 * independently of the client wrapper.
 */
const assert = require("node:assert/strict");
const http2 = require("node:http2");
const { after, before, test } = require("node:test");

const { createGrpcServer, PATHS } = require("../service/grpc_server.js");
const wire = require("../service/wire.js");

let server;
let port;

before(async () => {
  server = createGrpcServer();
  await new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  });
  port = server.address().port;
});

after(async () => {
  await new Promise((resolve) => server.close(resolve));
});

function rawCall(path, requestFrame) {
  return new Promise((resolve, reject) => {
    const session = http2.connect(`http://127.0.0.1:${port}`);
    const result = { headers: null, trailers: null, messages: [], body: null };
    let settled = false;

    const finish = (error) => {
      if (settled) return;
      settled = true;
      if (!session.destroyed && !session.closed) session.close();
      if (error !== undefined) reject(error);
      else resolve(result);
    };

    session.on("error", finish);
    const stream = session.request({
      ":method": "POST",
      ":path": path,
      "content-type": "application/grpc",
      "te": "trailers",
    });
    stream.on("response", (headers) => {
      result.headers = headers;
    });
    stream.on("trailers", (trailers) => {
      result.trailers = trailers;
    });
    stream.on("data", (chunk) => {
      result.body = result.body === null ? chunk : Buffer.concat([result.body, chunk]);
    });
    stream.on("end", () => {
      try {
        const decoder = new wire.FrameDecoder();
        result.messages = decoder.push(result.body ?? Buffer.alloc(0));
        decoder.finish();
      } catch (error) {
        finish(error);
        return;
      }
      finish();
    });
    stream.on("error", finish);
    stream.end(requestFrame);
  });
}

test("gRPC frame is a compressed flag plus a big-endian length", () => {
  const frame = wire.encodeFrame(Buffer.from([0x08, 0x01]));
  assert.deepEqual([...frame], [0, 0, 0, 0, 2, 0x08, 0x01]);
  assert.deepEqual([...wire.decodeFrame(frame)], [0x08, 0x01]);
});

test("the incremental frame decoder accepts a frame split across chunks", () => {
  const payload = Buffer.from([0x08, 0x01]);
  const frame = wire.encodeFrame(payload);
  const decoder = new wire.FrameDecoder();
  assert.deepEqual(decoder.push(frame.subarray(0, 3)), []);
  assert.equal(decoder.pendingBytes, 3);
  assert.deepEqual(decoder.push(frame.subarray(3)), [payload]);
  decoder.finish();
});

test("reading messages round-trip with exact field numbers and values", () => {
  const reading = { siteId: "site-a", watts: 4120, atMs: 1762300000000 };
  const encoded = wire.encodeReading(reading);
  // field 1 (site_id), field 2 (watts), field 3 (at_ms)
  assert.equal(encoded[0], 0x0a);
  assert.match(encoded.toString("latin1"), /site-a/u);
  assert.deepEqual(wire.decodeReading(encoded), reading);
});

test("optional limit preserves absent versus explicit zero", () => {
  const absent = wire.decodeStreamReadingsRequest(
    wire.encodeStreamReadingsRequest({ siteId: "site-a" }),
  );
  assert.equal(absent.limit, undefined);

  const zero = wire.decodeStreamReadingsRequest(
    wire.encodeStreamReadingsRequest({ siteId: "site-a", limit: 0 }),
  );
  assert.equal(zero.limit, 0);
});

test("GetReading serves one framed Reading with grpc-status 0", async () => {
  const result = await rawCall(
    PATHS.getReading,
    wire.encodeFrame(wire.encodeGetReadingRequest({ siteId: "site-a" })),
  );

  assert.equal(result.headers[":status"], 200);
  assert.match(result.headers["content-type"], /^application\/grpc/u);
  assert.equal(result.trailers["grpc-status"], "0");
  assert.equal(result.messages.length, 1);
  assert.deepEqual(wire.decodeReading(result.messages[0]), {
    siteId: "site-a",
    watts: 4120,
    atMs: 1762300000000,
  });
});

test("StreamReadings preserves source order and honours limit", async () => {
  const result = await rawCall(
    PATHS.streamReadings,
    wire.encodeFrame(wire.encodeStreamReadingsRequest({ siteId: "site-a", limit: 3 })),
  );

  assert.equal(result.trailers["grpc-status"], "0");
  const readings = result.messages.map((message) => wire.decodeReading(message));
  assert.equal(readings.length, 3);
  assert.deepEqual(
    readings.map((reading) => reading.atMs),
    [1762300000000, 1762300060000, 1762300120000],
  );
});

test("StreamReadings without a limit sends every reading", async () => {
  const result = await rawCall(
    PATHS.streamReadings,
    wire.encodeFrame(wire.encodeStreamReadingsRequest({ siteId: "site-b" })),
  );

  assert.equal(result.trailers["grpc-status"], "0");
  assert.equal(result.messages.length, 3);
  assert.deepEqual(
    result.messages.map((message) => wire.decodeReading(message).siteId),
    ["site-b", "site-b", "site-b"],
  );
});

test("unknown sites return NOT_FOUND and never an empty stream", async () => {
  const result = await rawCall(
    PATHS.streamReadings,
    wire.encodeFrame(wire.encodeStreamReadingsRequest({ siteId: "site-zz" })),
  );

  assert.equal(result.trailers["grpc-status"], "5");
  assert.equal(decodeURIComponent(result.trailers["grpc-message"]), "unknown_site");
  assert.equal(result.messages.length, 0);
});

test("a negative limit returns INVALID_ARGUMENT invalid_limit", async () => {
  const result = await rawCall(
    PATHS.streamReadings,
    wire.encodeFrame(wire.encodeStreamReadingsRequest({ siteId: "site-a", limit: -1 })),
  );

  assert.equal(result.trailers["grpc-status"], "3");
  assert.equal(decodeURIComponent(result.trailers["grpc-message"]), "invalid_limit");
  assert.equal(result.messages.length, 0);
});

test("an unknown method returns UNIMPLEMENTED", async () => {
  const result = await rawCall(
    "/energy.v1.EnergyService/NoSuchMethod",
    wire.encodeFrame(Buffer.alloc(0)),
  );

  assert.equal(result.trailers["grpc-status"], "12");
  assert.equal(decodeURIComponent(result.trailers["grpc-message"]), "unimplemented");
});

"use strict";

/**
 * Integration tests: a real gRPC client talks to a real gRPC server, and the
 * same fixtures are compared with the REST console path that must keep
 * working. No mocks and no in-process shortcuts.
 */
const assert = require("node:assert/strict");
const { after, before, test } = require("node:test");

const { createGrpcClient } = require("../service/grpc_client.js");
const { createGrpcServer } = require("../service/grpc_server.js");
const { createRestClient } = require("../service/rest_client.js");
const { createRestServer } = require("../service/rest_server.js");

let grpcServer;
let restServer;
let grpc;
let rest;

async function listen(server) {
  await new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  });
  return server.address().port;
}

before(async () => {
  grpcServer = createGrpcServer();
  restServer = createRestServer();
  const [grpcPort, restPort] = await Promise.all([listen(grpcServer), listen(restServer)]);
  grpc = createGrpcClient(grpcPort);
  rest = createRestClient(restPort);
});

after(async () => {
  grpc.close();
  await Promise.all([
    new Promise((resolve) => grpcServer.close(resolve)),
    new Promise((resolve) => restServer.close(resolve)),
  ]);
});

test("GetReading returns the same values as the REST console for every site", async () => {
  for (const siteId of ["site-a", "site-b"]) {
    assert.deepEqual(await grpc.getReading(siteId), await rest.getReading(siteId));
  }
});

test("StreamReadings matches REST ordering and limit semantics", async () => {
  assert.deepEqual(await grpc.getReadings("site-a", 3), await rest.getReadings("site-a", 3));
  assert.deepEqual(await grpc.getReadings("site-a"), await rest.getReadings("site-a"));
  assert.deepEqual(await grpc.getReadings("site-a", 0), await rest.getReadings("site-a", 0));
  assert.deepEqual(await grpc.getReadings("site-a", 99), await rest.getReadings("site-a", 99));
});

test("atMs crosses the wire as the exact epoch millisecond integer", async () => {
  const readings = await grpc.getReadings("site-a");
  assert.deepEqual(
    readings.map((reading) => reading.atMs),
    [1762300000000, 1762300060000, 1762300120000, 1762300180000, 1762300240000, 1762300300000],
  );
  for (const reading of readings) {
    assert.equal(Number.isInteger(reading.atMs), true);
    assert.equal(Number.isInteger(reading.watts), true);
  }
});

test("streamReadings yields readings as a stream, not one batch", async () => {
  const seen = [];
  for await (const reading of grpc.streamReadings("site-b")) seen.push(reading);
  assert.deepEqual(seen, await grpc.getReadings("site-b"));
  assert.equal(seen.length, 3);
});

test("unknown sites reject with unknown_site, not an empty result", async () => {
  await assert.rejects(() => grpc.getReading("site-zz"), /unknown_site/u);
  await assert.rejects(() => grpc.getReadings("site-zz"), /unknown_site/u);
  await assert.rejects(() => rest.getReading("site-zz"), /unknown_site/u);
});

test("invalid limits reject with invalid_limit through the gRPC client", async () => {
  await assert.rejects(() => grpc.getReadings("site-a", -1), /invalid_limit/u);
  await assert.rejects(() => grpc.getReadings("site-a", 1.5), /invalid_limit/u);
  await assert.rejects(() => rest.getReadings("site-a", 1.5), /invalid_limit/u);
});

test("concurrent calls stay isolated and correct", async () => {
  const calls = [];
  for (let index = 0; index < 20; index += 1) {
    const siteId = index % 2 === 0 ? "site-a" : "site-b";
    calls.push(grpc.getReading(siteId));
  }
  const readings = await Promise.all(calls);
  for (const [index, reading] of readings.entries()) {
    assert.equal(reading.siteId, index % 2 === 0 ? "site-a" : "site-b");
    assert.equal(reading.atMs, 1762300000000);
  }
});
